<?php require_once 'includes/auth.php';require_login();$items=cart_items();if(!$items){header('Location: cart.php');exit;}$subtotal=0;foreach($items as $i)$subtotal+=sale_price($i)*(int)$i['quantity'];$shipping=$subtotal?8:0;$tax=$subtotal*.05;$total=$subtotal+$shipping+$tax;$u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']);$phone=trim($_POST['phone']);$address=trim($_POST['address']);$city=trim($_POST['city']);$country=trim($_POST['country']);$postal=trim($_POST['postal_code']);$method=$_POST['payment_method']??'cod';if(!$name||!$phone||!$address||!$city||!$country||!$postal||!in_array($method,['cod','card','paypal'],true)){flash('error','Please complete all checkout fields.');}else{try{$pdo->beginTransaction();$locked=[];foreach($items as $i){$s=$pdo->prepare("SELECT id,name,stock,price,discount,main_image FROM products WHERE id=? AND status='active' FOR UPDATE");$s->execute([$i['product_id']??$i['id']]);$p=$s->fetch();if(!$p||$p['stock']<(int)$i['quantity'])throw new Exception("Insufficient stock for {$i['name']}.");$locked[]=$p;}$s=$pdo->prepare("INSERT INTO orders(user_id,customer_name,customer_email,phone,shipping_address,city,country,postal_code,subtotal,discount,shipping,tax,total,payment_method,payment_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$s->execute([$u['id'],$name,$u['email'],$phone,$address,$city,$country,$postal,$subtotal,0,$shipping,$tax,$total,$method,$method==='card'?'paid':'pending']);$oid=(int)$pdo->lastInsertId();$itemStmt=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,category_name,product_image,unit_price,quantity,discount,subtotal) SELECT ?,p.id,p.name,c.name,p.main_image,p.price,?,?,? FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?");$stockStmt=$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=?");foreach($items as $i){$pid=(int)($i['product_id']??$i['id']);$p=array_values(array_filter($locked,fn($x)=>(int)$x['id']===$pid))[0];$unit=sale_price($p);$sub=$unit*(int)$i['quantity'];$itemStmt->execute([$oid,$i['quantity'],$p['discount'],$sub,$pid]);$stockStmt->execute([(int)$i['quantity'],$pid]);}$pdo->prepare("DELETE FROM cart WHERE user_id=?")->execute([$u['id']]);$pdo->commit();header("Location: order-success.php?id=$oid");exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}}}
$page_title='Checkout';require 'includes/header.php';?>
<div class="container page-title"><span class="eyebrow">Secure checkout</span><h1>Complete your order</h1></div><div class="container cart-layout section" style="padding-top:10px"><form class="form-card" style="max-width:none;margin:0" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field"><label>Full name</label><input class="input" name="name" value="<?=e($u['name'])?>" required></div><div class="field"><label>Phone</label><input class="input" name="phone" value="<?=e($u['phone'])?>" required></div></div><div class="field"><label>Address</label><input class="input" name="address" required></div><div class="form-grid"><div class="field"><label>City</label><input class="input" name="city" required></div><div class="field"><label>Country</label><input class="input" name="country" value="United States" required></div></div><div class="field"><label>Postal code</label><input class="input" name="postal_code" required></div><div class="field"><label>Payment method</label><select name="payment_method"><option value="cod">Cash on Delivery</option><option value="card">Credit/Debit Card (UI demo)</option><option value="paypal">PayPal (placeholder)</option></select></div><button class="btn">Place order · <?=money($total)?></button><p style="font-size:12px;color:#777">Card numbers and CVV are never stored by this demo checkout.</p></form><aside class="summary"><h2>Order summary</h2><?php foreach($items as $i):?><div class="summary-row"><span><?=e($i['name'])?> × <?=$i['quantity']?></span><span><?=money(sale_price($i)*$i['quantity'])?></span></div><?php endforeach;?><div class="summary-row summary-total"><span>Total</span><b><?=money($total)?></b></div></aside></div><?php require 'includes/footer.php';?>
